window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b33d8c310e65facf"]={"versions": [{"id": "FIG-b33d8c310e65facf", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm mit Interaktionsreferenz (<code>ref</code>-Fragment).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten, geordneten Herunterfahrprozesses (Graceful Shutdown) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Koordination zwischen den Basissystem-Funktionsclustern (<em>State Management</em>, <em>Execution Management</em>, <em>Platform Health Management</em>), dem zugrundeliegenden POSIX-Betriebssystem und einer plattformspezifischen Shutdown-Applikation (<code>shutdownApp</code>), um Race Conditions, fehlerhafte Health-Reaktionen und Datenverlust beim ECU-Power-Down zu vermeiden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien / Entitäten:</strong></li>\n<li><code>«aapFunctionalCluster» :State Management</code> (SM): Entscheidet über systemweite Zustandsübergänge und initiiert den Plattform-Shutdown.</li>\n<li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Verantwortlich für das Prozess-Lifecycle-Management sowie die Signalisierung auf Betriebssystemebene.</li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Überwacht Applikationszustände (Alive/Deadline/Logical Supervision).</li>\n<li><code>:Operating System</code>: POSIX-konformes Betriebssystem (Prozess- und Signalverwaltung, Systemaufrufe).</li>\n<li><code>shutdownApp</code>: Spezifische, kurzlebige Adaptive Application zur Ausführung dedizierter Abschlussroutinen (z. B. NVM-Flush, Bus-Deinitialisierung).</li>\n<li><strong>Stereotypen:</strong> <code>«aapFunctionalCluster»</code> (Standardisierter Kern-Cluster der Adaptive Platform Foundation).</li>\n<li><strong>Schnittstellen & Interaktionsprimitive:</strong></li>\n<li><code>StopOffer()</code>: Service-Deregistrierung (ara::com / Service Discovery) des PHM.</li>\n<li><code>ref Change Function Group State (Shutdown)</code>: Gekapseltes Sequenzfragment zur Überführung einer Function Group in den Target State <code>Off</code>/<code>Shutdown</code>.</li>\n<li><code>SIGTERM()</code>: Standardisiertes POSIX-Terminierungssignal (Graceful Termination).</li>\n<li><code>exec()</code>: POSIX-Systemaufruf zur Prozessinstanziierung.</li>\n<li><code>main()</code>: Einstiegspunkt der Shutdown-Applikation.</li>\n<li><code>shutdown()</code>: Systemaufruf zur Einleitung des hardwarenahen Kernel-/OS-Shutdowns.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Deaktivierung der Überwachung (Pre-Shutdown):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:State Management</code> sendet <code>StopOffer()</code> an <code>:Platform Health Management</code>. Das PHM stellt seinen Service ein, um zu verhindern, dass das reguläre Beenden von Applikationen fälschlicherweise als Deadline-/Alive-Supervision-Verletzung interpretiert wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang der Funktionsgruppe (<code>ref</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in das Interaktionsfragment <em>Change Function Group State (Shutdown)</em> unter Leitung des <code>:Execution Management</code>.</li>\n<li>EM sendet <code>SIGTERM()</code> an <code>:Platform Health Management</code>; PHM terminiert (<code>X</code>).</li>\n<li>EM startet über das <code>:Operating System</code> mittels <code>exec()</code> die dedizierte <code>shutdownApp</code>.</li>\n<li>OS übergibt die Kontrolle über <code>main()</code> an <code>shutdownApp</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattform-Abschluss & finale Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abarbeitung der Shutdown-Aufgaben ruft <code>shutdownApp</code> <code>shutdown()</code> auf dem <code>:Operating System</code> auf.</li>\n<li>Das <code>:Operating System</code> übernimmt die finale Phasenterminierung und sendet parallel bzw. sequenziell <code>SIGTERM()</code> an die verbleibenden Prozesse:</li>\n<li><code>:State Management</code> (terminiert <code>X</code>)</li>\n<li><code>:Execution Management</code> (terminiert <code>X</code>)</li>\n<li><code>shutdownApp</code> (terminiert sich nach Abschluss via Signal <code>X</code>)</li>\n<li>Alle Plattform-Dienste sind beendet; das OS kann die CPU stromlos schalten oder in den Standby versetzen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Signal-Handling (<code>SIGTERM</code>):</strong> Alle Adaptive Applications sowie Platform Clusters müssen zwingend einen non-blocking Signal-Handler für <code>SIGTERM</code> registrieren. Nach Signaleingang muss der Prozess alle Ressourcen freigeben und sich vor Ablauf des im Manifest konfigurierten <code>terminationTimeout</code> beenden; andernfalls erzwingt EM/OS die Beendigung via <code>SIGKILL</code>.</li>\n<li><strong>PHM-Supervision-Lifecycle:</strong> Entwickler müssen sicherstellen, dass PHM vor den zu überwachenden Applikationen oder synchron mit der Deaktivierung der jeweiligen Function Group deregistriert wird (<code>StopOffer</code>), um Fehlereinträge im Diagnostic Event Manager (Dem/DM) oder unberechtigte Recovery-Aktionen (z. B. Watchdog-Reset) während des Herunterfahrens zu unterbinden.</li>\n<li><strong>Rolle der <code>shutdownApp</code>:</strong> Die Applikation dient als definierter Synchronisationspunkt. Sie darf keine Abhängigkeiten zu bereits beendeten Functional Clustern (z. B. PHM) aufweisen und muss zustandslose Hardware-Deinitialisierungen oder persistente Speicheroperationen synchron vor dem <code>shutdown()</code>-Call abschließen.</li>\n</ul>"}, {"id": "FIG-14125caccf7b40f7", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm mit Interaktionsreferenz (<code>ref</code>-Fragment).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten, geordneten Herunterfahrprozesses (Graceful Shutdown) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Koordination zwischen den Basissystem-Funktionsclustern (<em>State Management</em>, <em>Execution Management</em>, <em>Platform Health Management</em>), dem zugrundeliegenden POSIX-Betriebssystem und einer plattformspezifischen Shutdown-Applikation (<code>shutdownApp</code>), um Race Conditions, fehlerhafte Health-Reaktionen und Datenverlust beim ECU-Power-Down zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien / Entitäten:</strong></li>\n<li><code>«aapFunctionalCluster» :State Management</code> (SM): Entscheidet über systemweite Zustandsübergänge und initiiert den Plattform-Shutdown.</li>\n<li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Verantwortlich für das Prozess-Lifecycle-Management sowie die Signalisierung auf Betriebssystemebene.</li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Überwacht Applikationszustände (Alive/Deadline/Logical Supervision).</li>\n<li><code>:Operating System</code>: POSIX-konformes Betriebssystem (Prozess- und Signalverwaltung, Systemaufrufe).</li>\n<li><code>shutdownApp</code>: Spezifische, kurzlebige Adaptive Application zur Ausführung dedizierter Abschlussroutinen (z. B. NVM-Flush, Bus-Deinitialisierung).</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Standardisierter Kern-Cluster der Adaptive Platform Foundation.</li>\n<li><code>«aapInformative»</code>: Kennzeichnung nicht-normativer, beispielhafter Interaktionen oder betriebssystemspezifischer Aufrufe.</li>\n<li><strong>Schnittstellen & Interaktionsprimitive:</strong></li>\n<li><code>StopOffer()</code>: Service-Deregistrierung (ara::com / Service Discovery) des PHM.</li>\n<li><code>ref Change Function Group State (Shutdown)</code>: Gekapseltes Sequenzfragment zur Überführung einer Function Group in den Target State <code>Off</code>/<code>Shutdown</code>.</li>\n<li><code>SIGTERM()</code>: Standardisiertes POSIX-Terminierungssignal (Graceful Termination).</li>\n<li><code>exec() «aapInformative»</code>: Als informativ gekennzeichneter POSIX-Systemaufruf zur Prozessinstanziierung.</li>\n<li><code>main() «aapInformative»</code>: Als informativ gekennzeichneter Einstiegspunkt der Shutdown-Applikation.</li>\n<li><code>shutdown() «aapInformative»</code>: Als informativ gekennzeichneter Systemaufruf zur Einleitung des hardwarenahen Kernel-/OS-Shutdowns.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Deaktivierung der Überwachung (Pre-Shutdown):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:State Management</code> sendet <code>StopOffer()</code> an <code>:Platform Health Management</code>. Das PHM stellt seinen Service ein, um zu verhindern, dass das reguläre Beenden von Applikationen fälschlicherweise als Deadline-/Alive-Supervision-Verletzung interpretiert wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang der Funktionsgruppe (<code>ref</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in das Interaktionsfragment <em>Change Function Group State (Shutdown)</em> unter Leitung des <code>:Execution Management</code>.</li>\n<li>EM sendet <code>SIGTERM()</code> an <code>:Platform Health Management</code>; PHM terminiert (<code>X</code>).</li>\n<li>EM startet über das <code>:Operating System</code> mittels <code>exec()</code> die dedizierte <code>shutdownApp</code>.</li>\n<li>OS übergibt die Kontrolle über <code>main()</code> an <code>shutdownApp</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattform-Abschluss & finale Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abarbeitung der Shutdown-Aufgaben ruft <code>shutdownApp</code> <code>shutdown()</code> auf dem <code>:Operating System</code> auf.</li>\n<li>Das <code>:Operating System</code> übernimmt die finale Phasenterminierung und sendet parallel bzw. sequenziell <code>SIGTERM()</code> an die verbleibenden Prozesse:</li>\n<li><code>:State Management</code> (terminiert <code>X</code>)</li>\n<li><code>:Execution Management</code> (terminiert <code>X</code>)</li>\n<li><code>shutdownApp</code> (terminiert sich nach Abschluss via Signal <code>X</code>)</li>\n<li>Alle Plattform-Dienste sind beendet; das OS kann die CPU stromlos schalten oder in den Standby versetzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Verbindlichkeit & Normativitätsgrad:</strong> Das Sequenzdiagramm dokumentiert das koordinierte Herunterfahren der Adaptive Platform. Durch die Kennzeichnung von <code>exec()</code>, <code>main()</code> und <code>shutdown()</code> mit dem Stereotyp <code>«aapInformative»</code> wird klargestellt, dass konkrete Betriebssystemaufrufe und Spracheinstiegspunkte beispielhaft und nicht-normativ für die AUTOSAR AP Spezifikation sind; normativ verbindlich ist die Interaktionsabfolge der Plattform-Cluster und die Signalsteuerung via <code>SIGTERM</code>.</li>\n<li><strong>POSIX- und Signal-Semantik:</strong> Die Terminierung von Plattform- und Applikationsprozessen erfolgt standardisiert über POSIX <code>SIGTERM</code>. Applikationen müssen innerhalb des konfigurierten Timeouts reagieren und sich sauber beenden, bevor Zwangsmaßnahmen des OS greifen.</li>\n<li><strong>Rolle der <code>shutdownApp</code>:</strong> Die dedizierte Shutdown-Applikation kapselt projektspezifische Abschlussarbeiten (flüchtige Daten sichern, Netzwerkkommunikation abmelden). Erst nach deren Beendigung führt das Betriebssystem den hardwarenahen Shutdown durch.</li>\n</ul>"}, {"id": "FIG-311ccf5ecf647805", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm mit Interaktionsreferenz (<code>ref</code>-Fragment).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten, geordneten Herunterfahrprozesses (Graceful Shutdown) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Funktionale Einordnung:</strong> Koordination zwischen den Basissystem-Funktionsclustern (<em>State Management</em>, <em>Execution Management</em>, <em>Platform Health Management</em>), dem zugrundeliegenden POSIX-Betriebssystem und einer plattformspezifischen Shutdown-Applikation (<code>shutdownApp</code>), um Race Conditions, fehlerhafte Health-Reaktionen und Datenverlust beim ECU-Power-Down zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien / Entitäten:</strong></li>\n<li><code>«aapFunctionalCluster» :State Management</code> (SM): Entscheidet über systemweite Zustandsübergänge und initiiert den Plattform-Shutdown.</li>\n<li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Verantwortlich für das Prozess-Lifecycle-Management sowie die Signalisierung auf Betriebssystemebene.</li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Überwacht Applikationszustände (Alive/Deadline/Logical Supervision).</li>\n<li><code>:Operating System</code>: POSIX-konformes Betriebssystem (Prozess- und Signalverwaltung, Systemaufrufe).</li>\n<li><code>shutdownApp</code>: Spezifische, kurzlebige Adaptive Application zur Ausführung dedizierter Abschlussroutinen (z. B. NVM-Flush, Bus-Deinitialisierung).</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Standardisierter Kern-Cluster der Adaptive Platform Foundation.</li>\n<li><code>«aapInformative»</code>: Kennzeichnung nicht-normativer, beispielhafter Interaktionen oder betriebssystemspezifischer Aufrufe.</li>\n<li><strong>Schnittstellen & Interaktionsprimitive:</strong></li>\n<li><code>StopOffer()</code>: Service-Deregistrierung (ara::com / Service Discovery) des PHM.</li>\n<li><code>ref Change Function Group State (Shutdown)</code>: Gekapseltes Sequenzfragment zur Überführung einer Function Group in den Target State <code>Off</code>/<code>Shutdown</code>.</li>\n<li><code>SIGTERM()</code>: Standardisiertes POSIX-Terminierungssignal (Graceful Termination).</li>\n<li><code>exec() «aapInformative»</code>: Als informativ gekennzeichneter POSIX-Systemaufruf zur Prozessinstanziierung.</li>\n<li><code>main() «aapInformative»</code>: Als informativ gekennzeichneter Einstiegspunkt der Shutdown-Applikation.</li>\n<li><code>shutdown() «aapInformative»</code>: Als informativ gekennzeichneter Systemaufruf zur Einleitung des hardwarenahen Kernel-/OS-Shutdowns.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Deaktivierung der Überwachung (Pre-Shutdown):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:State Management</code> sendet <code>StopOffer()</code> an <code>:Platform Health Management</code>. Das PHM stellt seinen Service ein, um zu verhindern, dass das reguläre Beenden von Applikationen fälschlicherweise als Deadline-/Alive-Supervision-Verletzung interpretiert wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang der Funktionsgruppe (<code>ref</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in das Interaktionsfragment <em>Change Function Group State (Shutdown)</em> unter Leitung des <code>:Execution Management</code>.</li>\n<li>EM sendet <code>SIGTERM()</code> an <code>:Platform Health Management</code>; PHM terminiert (<code>X</code>).</li>\n<li>EM startet über das <code>:Operating System</code> mittels <code>exec()</code> die dedizierte <code>shutdownApp</code>.</li>\n<li>OS übergibt die Kontrolle über <code>main()</code> an <code>shutdownApp</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattform-Abschluss & finale Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abarbeitung der Shutdown-Aufgaben ruft <code>shutdownApp</code> <code>shutdown()</code> auf dem <code>:Operating System</code> auf.</li>\n<li>Das <code>:Operating System</code> übernimmt die finale Phasenterminierung und sendet parallel bzw. sequenziell <code>SIGTERM()</code> an die verbleibenden Prozesse:</li>\n<li><code>:State Management</code> (terminiert <code>X</code>)</li>\n<li><code>:Execution Management</code> (terminiert <code>X</code>)</li>\n<li><code>shutdownApp</code> (terminiert sich nach Abschluss via Signal <code>X</code>)</li>\n<li>Alle Plattform-Dienste sind beendet; das OS kann die CPU stromlos schalten oder in den Standby versetzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektonische Verbindlichkeit & Normativitätsgrad:</strong> Das Sequenzdiagramm dokumentiert das koordinierte Herunterfahren der Adaptive Platform. Durch die Kennzeichnung von <code>exec()</code>, <code>main()</code> und <code>shutdown()</code> mit dem Stereotyp <code>«aapInformative»</code> wird klargestellt, dass konkrete Betriebssystemaufrufe und Spracheinstiegspunkte beispielhaft und nicht-normativ für die AUTOSAR AP Spezifikation sind; normativ verbindlich ist die Interaktionsabfolge der Plattform-Cluster und die Signalsteuerung via <code>SIGTERM</code>.</li>\n<li><strong>POSIX- und Signal-Semantik:</strong> Die Terminierung von Plattform- und Applikationsprozessen erfolgt standardisiert über POSIX <code>SIGTERM</code>. Applikationen müssen innerhalb des konfigurierten Timeouts reagieren und sich sauber beenden, bevor Zwangsmaßnahmen des OS greifen.</li>\n<li><strong>Rolle der <code>shutdownApp</code>:</strong> Die dedizierte Shutdown-Applikation kapselt projektspezifische Abschlussarbeiten (flüchtige Daten sichern, Netzwerkkommunikation abmelden). Erst nach deren Beendigung führt das Betriebssystem den hardwarenahen Shutdown durch.</li>\n</ul>"}], "trans": [{"from": "FIG-b33d8c310e65facf", "to": "FIG-14125caccf7b40f7", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>exec()</code>: Ergänzung des Stereotyps <code>«aapInformative»</code> an der Interaktionsnachricht von <code>:Execution Management</code> an <code>:Operating System</code>.</li>\n<li><code>main()</code>: Ergänzung des Stereotyps <code>«aapInformative»</code> an der Interaktionsnachricht von <code>:Operating System</code> an <code>shutdownApp</code>.</li>\n<li><code>shutdown()</code>: Ergänzung des Stereotyps <code>«aapInformative»</code> an der Interaktionsnachricht von <code>shutdownApp</code> an <code>:Operating System</code>.</li>\n</ul>"}, {"from": "FIG-14125caccf7b40f7", "to": "FIG-311ccf5ecf647805", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
